ALTER TABLE own_judgments ADD CONSTRAINT own_judgments_origin_check CHECK (origin IN ('deterministic', 'model', 'file') AND (origin <> 'model' OR (prompt_version <> '' AND model_version <> '' AND model_version NOT IN ('file:assistant-file', 'file:human-file'))) AND (origin <> 'file' OR (prompt_version <> '' AND model_version IN ('file:assistant-file', 'file:human-file') AND model_receipt_id IS NULL))) NOT VALID;
